export const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');

export function sortModelsAlphabetically(models = []) {
  return [...models].sort((a, b) => {
    const leftLetter = a?.letter ?? '';
    const rightLetter = b?.letter ?? '';
    return leftLetter.localeCompare(rightLetter, undefined, { sensitivity: 'base' });
  });
}

export function buildAlphabetModelSlots(models = [], alphabet = ALPHABET) {
  const modelMap = new Map(
    (models || [])
      .filter(Boolean)
      .map(model => [String(model.letter || '').toUpperCase(), model])
  );

  return alphabet.map(letter => {
    const model = modelMap.get(letter);
    return model ? { ...model, letter } : null;
  });
}
